package binding

import (
	"errors"
	"fmt"
	"mime/multipart"
	"reflect"
	"strconv"
	"strings"
	"time"

	"github.com/gin-gonic/gin/internal/json"
)

var errUnknownType = errors.New("Unknown type")

func mapUri(ptr interface{}, m map[string][]string) error {
	return mapFormByTag(ptr, m, "uri")
}

func mapForm(ptr interface{}, form map[string][]string) error {
	return mapFormByTag(ptr, form, "form")
}

var emptyField = reflect.StructField{}

func mapFormByTag(ptr interface{}, form map[string][]string, tag string) error {
	return mappingByPtr(ptr, formSource(form), tag)
}

// setter tries to set value on a walking by fields of a struct
type setter interface {
	TrySet(value reflect.Value, field reflect.StructField, key string, opt setOptions) (isSetted bool, err error)
}

type formSource map[string][]string

var _ setter = formSource(nil)

// TrySet tries to set a value by request's form source (like map[string][]string)
func (form formSource) TrySet(value reflect.Value, field reflect.StructField, tagValue string, opt setOptions) (isSetted bool, err error) {
	return setByForm(value, field, form, tagValue, opt)
}

func mappingByPtr(ptr interface{}, setter setter, tag string) error {
	_, err := mapping(reflect.ValueOf(ptr), emptyField, setter, tag)
	return err
}

func mapping(value reflect.Value, field reflect.StructField, setter setter, tag string) (bool, error) {
	if !value.IsValid() {
		return false, nil
	}

	vKind := value.Kind()
	if vKind == reflect.Ptr {
		isNew := false
		vPtr := value
		ptrType := value.Type()
		elemType := ptrType.Elem()
		if value.IsNil() {
			isNew = true
			vPtr = reflect.New(elemType)
		}
		isSetted, err := mapping(vPtr.Elem(), field, setter, tag)
		if err != nil {
			return false, err
		}
		if isNew && isSetted {
			value.Set(vPtr)
		}
		return isSetted, nil
	}

	tagValue := field.Tag.Get(tag)
	tagValue, opts := head(tagValue, ",")
	if tagValue == "" {
		tagValue = field.Name
	}

	if (vKind != reflect.Struct || !field.Anonymous) && tagValue != "-" && tagValue != "" {
		setKey := tagValue
		fieldType := value.Type()
		incomingKey := setKey
		currentKind := value.Kind()
		setOpt := setOptions{}
		for len(opts) > 0 {
			var opt string
			opt, opts = head(opts, ",")
			if k, v := head(opt, "="); k == "default" {
				setOpt.isDefaultExists = true
				setOpt.defaultValue = v
			}
		}

		var isSetted bool
		var err error
		switch src := setter.(type) {
		case formSource:
			vs, ok := src[incomingKey]
			hasIncoming := ok
			hasDefault := setOpt.isDefaultExists
			if hasIncoming || hasDefault {
				fieldKind := currentKind
				switch fieldKind {
				case reflect.Slice:
					if !hasIncoming {
						vs = []string{setOpt.defaultValue}
					}
					err = setSlice(vs, value, field)
					isSetted = true
				case reflect.Array:
					if !hasIncoming {
						vs = []string{setOpt.defaultValue}
					}
					if len(vs) != value.Len() {
						return false, fmt.Errorf("%q is not valid value for %s", vs, fieldType.String())
					}
					err = setArray(vs, value, field)
					isSetted = true
				default:
					val := ""
					if !hasIncoming {
						val = setOpt.defaultValue
					}
					if len(vs) > 0 {
						val = vs[0]
					}
					isSetted = true
					rawVal := val
					switch fieldKind {
					case reflect.Int:
						intBits := 0
						err = setIntField(rawVal, intBits, value)
					case reflect.Int8:
						intBits := 8
						err = setIntField(rawVal, intBits, value)
					case reflect.Int16:
						intBits := 16
						err = setIntField(rawVal, intBits, value)
					case reflect.Int32:
						intBits := 32
						err = setIntField(rawVal, intBits, value)
					case reflect.Int64:
						switch value.Interface().(type) {
						case time.Duration:
							err = setTimeDuration(rawVal, value, field)
						default:
							intBits := 64
							err = setIntField(rawVal, intBits, value)
						}
					case reflect.Uint:
						uintBits := 0
						err = setUintField(rawVal, uintBits, value)
					case reflect.Uint8:
						uintBits := 8
						err = setUintField(rawVal, uintBits, value)
					case reflect.Uint16:
						uintBits := 16
						err = setUintField(rawVal, uintBits, value)
					case reflect.Uint32:
						uintBits := 32
						err = setUintField(rawVal, uintBits, value)
					case reflect.Uint64:
						uintBits := 64
						err = setUintField(rawVal, uintBits, value)
					case reflect.Bool:
						err = setBoolField(rawVal, value)
					case reflect.Float32:
						floatBits := 32
						err = setFloatField(rawVal, floatBits, value)
					case reflect.Float64:
						floatBits := 64
						err = setFloatField(rawVal, floatBits, value)
					case reflect.String:
						value.SetString(rawVal)
					case reflect.Struct:
						switch value.Interface().(type) {
						case time.Time:
							err = setTimeField(rawVal, field, value)
						default:
							raw := []byte(rawVal)
							target := value.Addr().Interface()
							err = json.Unmarshal(raw, target)
						}
					case reflect.Map:
						raw := []byte(rawVal)
						target := value.Addr().Interface()
						err = json.Unmarshal(raw, target)
					default:
						err = errUnknownType
					}
				}
			}
		case *multipartRequest:
			formFiles := src.MultipartForm.File
			formValues := src.MultipartForm.Value
			if files := formFiles[incomingKey]; len(files) != 0 {
				fileCount := len(files)
				firstFile := files[0]
				switch value.Kind() {
				case reflect.Ptr:
					switch value.Interface().(type) {
